// stripe_checkout.rs - Stripe Payment Integration
use stripe::{
    Client, CreateCheckoutSession, CreateCheckoutSessionLineItems,
    CreateCheckoutSessionLineItemsPriceData, CreateCheckoutSessionLineItemsPriceDataProductData,
    CreateCheckoutSessionMode, CreateCheckoutSessionPaymentMethodTypes,
    CreateCustomer, CreateSubscription, CreateSubscriptionItems,
    Event, EventType, Webhook,
};\use serde::{Deserialize, Serialize};\use std::collections::HashMap;\use thiserror::Error;

#[derive(Error, Debug)]
pub enum StripeError {
    #[error("Stripe API error: {0}")]
    ApiError(#[from] stripe::StripeError),
    #[error("Webhook signature verification failed")]
    InvalidSignature,
    #[error("Customer not found: {0}")]
    CustomerNotFound(String),
    #[error("Subscription not found: {0}")]
    SubscriptionNotFound(String),
    #[error("Invalid event type: {0}")]
    InvalidEventType(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CheckoutSessionRequest {
    pub customer_email: Option<String>,
    pub customer_id: Option<String>,
    pub line_items: Vec<LineItem>,
    pub success_url: String,
    pub cancel_url: String,
    pub mode: CheckoutMode,
    pub metadata: HashMap<String, String>,
    pub allow_promotion_codes: bool,
    pub billing_address_collection: Option<BillingAddressCollection>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LineItem {
    pub price_id: Option<String>,
    pub product_name: Option<String>,
    pub product_description: Option<String>,
    pub unit_amount: Option<i64>,
    pub currency: String,
    pub quantity: i64,
    pub recurring: Option<RecurringInterval>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RecurringInterval {
    Day,
    Week,
    Month,
    Year,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CheckoutMode {
    Payment,
    Setup,
    Subscription,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum BillingAddressCollection {
    Auto,
    Required,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CheckoutSessionResponse {
    pub session_id: String,
    pub url: String,
    pub expires_at: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CustomerResponse {
    pub id: String,
    pub email: Option<String>,
    pub name: Option<String>,
}

pub struct StripeService {
    client: Client,
    webhook_secret: String,
}

impl StripeService {
    pub fn new(secret_key: String, webhook_secret: String) -> Self {
        Self {
            Client::new(secret_key),
            webhook_secret,
        }
    }

    pub async fn create_checkout_session(&self, req: CheckoutSessionRequest) -> Result<CheckoutSessionResponse, StripeError> {
        let mut line_items = Vec::new();

        for item in req.line_items {
            let price_data = if let Some(price_id) = item.price_id {
                CreateCheckoutSessionLineItemsPriceData {
                    currency: item.currency,
                    product_data: None,
                    unit_amount: None,
                    recurring: item.recurring.map(|r| stripe::CreateCheckoutSessionLineItemsPriceDataRecurring {
                        interval: match r {
                            RecurringInterval::Day => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Day,
                            RecurringInterval::Week => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Week,
                            RecurringInterval::Month => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Month,
                            RecurringInterval::Year => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Year,
                        },
                        interval_count: None,
                    }),
                    product: None,
                    ..Default::default()
                }
            } else {
                CreateCheckoutSessionLineItemsPriceData {
                    currency: item.currency,
                    product_data: Some(CreateCheckoutSessionLineItemsPriceDataProductData {
                        name: item.product_name.unwrap_or_default(),
                        description: item.product_description,
                        images: None,
                        metadata: None,
                    }),
                    unit_amount: item.unit_amount,
                    recurring: item.recurring.map(|r| stripe::CreateCheckoutSessionLineItemsPriceDataRecurring {
                        interval: match r {
                            RecurringInterval::Day => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Day,
                            RecurringInterval::Week => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Week,
                            RecurringInterval::Month => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Month,
                            RecurringInterval::Year => stripe::CreateCheckoutSessionLineItemsPriceDataRecurringInterval::Year,
                        },
                        interval_count: None,
                    }),
                    product: None,
                    ..Default::default()
                }
            };

            line_items.push(CreateCheckoutSessionLineItems {
                price_data: Some(price_data),
                quantity: Some(item.quantity),
                ..Default::default()
            });
        }

        let mut session_params = CreateCheckoutSession {
            line_items: Some(line_items),
            mode: Some(match req.mode {
                CheckoutMode::Payment => CreateCheckoutSessionMode::Payment,
                CheckoutMode::Setup => CreateCheckoutSessionMode::Setup,
                CheckoutMode::Subscription => CreateCheckoutSessionMode::Subscription,
            }),
            success_url: Some(req.success_url),
            cancel_url: Some(req.cancel_url),
            payment_method_types: Some(vec![CreateCheckoutSessionPaymentMethodTypes::Card]),
            allow_promotion_codes: Some(req.allow_promotion_codes),
            billing_address_collection: req.billing_address_collection.map(|b| match b {
                BillingAddressCollection::Auto => stripe::CreateCheckoutSessionBillingAddressCollection::Auto,
                BillingAddressCollection::Required => stripe::CreateCheckoutSessionBillingAddressCollection::Required,
            }),
            metadata: Some(req.metadata),
            ..Default::default()
        };

        if let Some(email) = req.customer_email {
            session_params.customer_email = Some(email);
        }
        if let Some(customer_id) = req.customer_id {
            session_params.customer = Some(customer_id);
        }

        let session = stripe::CheckoutSession::create(&self.client, session_params).await?;

        Ok(CheckoutSessionResponse {
            session_id: session.id.to_string(),
            url: session.url.unwrap_or_default(),
            expires_at: session.expires_at.unwrap_or(0),
        })
    }

    pub async fn create_customer(&self, email: String, name: Option<String>, metadata: HashMap<String, String>) -> Result<CustomerResponse, StripeError> {
        let mut params = CreateCustomer::new();
        params.email = Some(email);
        params.name = name;
        params.metadata = Some(metadata);

        let customer = stripe::Customer::create(&self.client, params).await?;
        Ok(CustomerResponse {
            id: customer.id.to_string(),
            email: customer.email,
            name: customer.name,
        })
    }

    pub async fn create_subscription(&self, customer_id: String, price_id: String, metadata: HashMap<String, String>) -> Result<stripe::Subscription, StripeError> {
        let mut params = CreateSubscription::new(customer_id);
        params.items = Some(vec![CreateSubscriptionItems {
            price: Some(price_id),
            quantity: Some(1),
            ..Default::default()
        }]);
        params.metadata = Some(metadata);

        let subscription = stripe::Subscription::create(&self.client, params).await?;
        Ok(subscription)
    }

    pub fn construct_webhook_event(&self, payload: &[u8], signature: &str) -> Result<Event, StripeError> {
        Webhook::construct_event(payload, signature, &self.webhook_secret)
            .map_err(|_| StripeError::InvalidSignature)
    }

    pub async fn handle_webhook(&self, event: Event) -> Result<(), StripeError> {
        match event.type_ {
            EventType::CheckoutSessionCompleted => {
                if let Some(session) = event.data.object.as_checkout_session() {
                    self.handle_checkout_completed(session).await?;
                }
            }
            EventType::CustomerSubscriptionCreated => {
                if let Some(sub) = event.data.object.as_subscription() {
                    self.handle_subscription_created(sub).await?;
                }
            }
            EventType::CustomerSubscriptionUpdated => {
                if let Some(sub) = event.data.object.as_subscription() {
                    self.handle_subscription_updated(sub).await?;
                }
            }
            EventType::CustomerSubscriptionDeleted => {
                if let Some(sub) = event.data.object.as_subscription() {
                    self.handle_subscription_cancelled(sub).await?;
                }
            }
            EventType::InvoicePaymentSucceeded => {
                if let Some(invoice) = event.data.object.as_invoice() {
                    self.handle_payment_succeeded(invoice).await?;
                }
            }
            EventType::InvoicePaymentFailed => {
                if let Some(invoice) = event.data.object.as_invoice() {
                    self.handle_payment_failed(invoice).await?;
                }
            }
            _ => {}
        }
        Ok(())
    }

    async fn handle_checkout_completed(&self, session: &stripe::CheckoutSession) -> Result<(), StripeError> {
        // Implement your logic here
        Ok(())
    }

    async fn handle_subscription_created(&self, sub: &stripe::Subscription) -> Result<(), StripeError> {
        Ok(())
    }

    async fn handle_subscription_updated(&self, sub: &stripe::Subscription) -> Result<(), StripeError> {
        Ok(())
    }

    async fn handle_subscription_cancelled(&self, sub: &stripe::Subscription) -> Result<(), StripeError> {
        Ok(())
    }

    async fn handle_payment_succeeded(&self, invoice: &stripe::Invoice) -> Result<(), StripeError> {
        Ok(())
    }

    async fn handle_payment_failed(&self, invoice: &stripe::Invoice) -> Result<(), StripeError> {
        Ok(())
    }
}
